g points"}, {"id": "7b244c80-0ba5-4be0-8f4f-cefcb046d503", "type": "concept", "title": "Linked lives"}, {"id": "3ca35ab8-38f8-46ad-ab7a-5e1f2a88d04b", "type": "concept", "title": "Cohort and historical context"}], "description": "A life-course lens shows how timing, transitions, accumulated advantage, and accumulated adversity shape development."}, {"id": "f0be1b2b-7bf4-4c79-97f5-46b6fb079dad", "type": "subtopic", "title": "Evidence-informed humility", "children": [{"id": "8bdf25bb-4402-49ca-a2f8-6d8605ef52d6", "type": "concept", "title": "Research literacy"}, {"id": "b4dfaf08-ccc8-4918-835e-914385812e5d", "type": "concept", "title": "Practice wisdom"}, {"id": "eae8bcbe-d5d1-428e-9a62-8e7c470eb63f", "type": "concept", "title": "Client narratives"}, {"id": "938122b8-add5-4a9a-9b92-0cf071c0af13", "type": "concept", "title": "Avoiding deterministic explanations"}], "description": "Students learn to use research while respecting uncertainty, lived experience, culture, and client self-understanding."}]}, {"id": "4cdec673-aeff-4e85-b5d8-6d3d2c903a4c", "type": "topic", "title": "Biopsychosocial-Spiritual Assessment and Case Formulation", "description": "Build an integrated assessment lens that connects biological, psychological, social, spiritual, cultural, and structural dimensions.", "children": [{"id": "78cd0541-cfdb-4815-bb5e-01edbdc064c3", "type": "subtopic", "title": "Biological dimensions", "children": [{"id": "631a7f83-eb4b-4113-a42c-2eba232b078d", "type": "concept", "title": "Health status"}, {"id": "91b7ae55-9947-4324-afba-2c9c317f60be", "type": "concept", "title": "Disability"}, {"id": "7f42ee00-44dc-4312-976c-459592a5c1f6", "type": "concept", "title": "Sleep, nutrition, and pain"}, {"id": "ca6d3181-b1be-4fa9-b8f1-f39c864bfdf5", "type": "concept", "title": "Genetic and neurodevelopmental factors"}], "description": "Biological factors matter, but they are always interpreted alongside environment, meaning, and resources."}, {"id": "0c830293-838b-4986-b798-0e11d4065fd1", "type": "subtopic", "title": "Psychological and relational dimensions", "children": [{"id": "44433c96-751c-414c-b5a0-04bff2038bbd", "type": "concept", "title": "Emotion regulation"}, {"id": "d1081156-3a18-449d-8fe7-c89aa6572b63", "type": "concept", "title": "Cognition and meaning-making"}, {"id": "926329d8-491a-4633-ab8f-c1157c100eea", "type": "concept", "title": "Attachment and relational patterns"}, {"id": "d2557783-4e56-49ae-b4c6-714d3ccbd4e9", "type": "concept", "title": "Motivation and coping"}], "description": "Psychological functioning develops in relationships and contexts rather than in isolation."}, {"id": "9c0a5f0f-2008-420e-94f7-b5c834915d8d", "type": "subtopic", "title": "Social, spiritual, and structural dimensions", "children": [{"id": "4fa61181-9aca-4d7a-9726-5d06a93f6b23", "type": "concept", "title": "Family and community supports"}, {"id": "2bf08ccf-1e7b-4e9c-a902-6e942d16dc46", "type": "concept", "title": "Culture and spirituality"}, {"id": "729ac187-97e8-4be4-b09f-8f75f0325e73", "type": "concept", "title": "Housing, income, and safety"}, {"id": "a2d29d66-fd4a-4b38-8ad0-dbc3df0211e1", "type": "concept", "title": "Discrimination and institutional barriers"}], "description": "A strong formulation includes the client's social world, identity, values, and structural conditions."}]}, {"id": "58dc3186-d6f3-4325-b78b-bbf4359b7d8d", "type": "topic", "title": "Major Theories of Human Development and Behavior", "description": "Compare developmental, psychodynamic, behavioral, cognitive, systems, feminist, critical, and strengths-based theories for social work use.", "children": [{"id": "f70c3ab2-d0a6-460e-ae26-e436b1fa4962", "type": "subtopic", "title": "Developmental theories", "children": [{"id": "135dba64-e181-46a7-877a-95c09f378a51", "type": "concept", "title": "Erikson"}, {"id": "6b5bb570-aa62-423b-b3f6-71c893336e0e", "type": "concept", "title": "Piaget"}, {"id": "8f0b4ab2-9148-419b-812d-594e98b731dc", "type": "concept", "title": "Vygotsky"}, {"