}], "description": "Identity development is shaped by culture, relationships, opportunity, and recognition."}, {"id": "b581e0e5-c8b8-42d9-b171-129063b4c24d", "type": "subtopic", "title": "Risk, resilience, and opportunity", "children": [{"id": "7d6e2c34-02ef-460c-9673-1a68517a8c47", "type": "concept", "title": "Substance use and risk behavior"}, {"id": "c45339bc-9b4d-4d91-9925-ee8f294e12ee", "type": "concept", "title": "Mental health and suicide risk"}, {"id": "fd0cfb58-3024-4464-a715-93cfae447017", "type": "concept", "title": "Juvenile justice contact"}, {"id": "f47a3cf9-731a-4783-a292-41a930c834f1", "type": "concept", "title": "Youth voice and leadership"}], "description": "Students learn to distinguish normative exploration from danger and to identify protective contexts."}]}, {"id": "96a057e6-ecf9-46fd-bd0f-3f8a2df05c04", "type": "topic", "title": "Young Adulthood: Intimacy, Education, Work, and Emerging Roles", "description": "Examine early adult transitions, relationships, work, identity, mental health, and social expectations.", "children": [{"id": "6d410365-d4bb-42b6-b5b2-028142339296", "type": "subtopic", "title": "Emerging adulthood and transitions", "children": [{"id": "0d31cc0e-c262-455e-96b8-be775ea7e2c7", "type": "concept", "title": "Emerging adulthood debates"}, {"id": "ec3bddf2-4d6b-4c5f-a789-7687ade60410", "type": "concept", "title": "Higher education and vocational pathways"}, {"id": "3825f065-4042-40ba-ade4-5724c859c004", "type": "concept", "title": "Housing transitions"}, {"id": "2535cdeb-dd0a-4883-997f-da6b7c5fa7ea", "type": "concept", "title": "Financial stress"}], "description": "Young adulthood often involves uneven transitions into work, education, independence, and adult identity."}, {"id": "a0133901-0e0c-48b7-af5d-7506d222e96e", "type": "subtopic", "title": "Relationships and intimacy", "children": [{"id": "50b6d4e9-5be5-484f-9ed4-740f9688fd6c", "type": "concept", "title": "Friendship networks"}, {"id": "5fd7470d-0b08-4866-bdea-4f652c35c56