update public.learning_paths
set
  title = 'Human Behavior in the Social Environment I',
  goal = 'Human Behavior in the Social Environment I',
  summary = 'This syllabus follows a lifespan-development base while incorporating biopsychosocial-spiritual formulation, neuroscience, structural context, trauma/ACEs, culture and power analysis, and applied case assessment. This sequence fits a Social Work core course that prepares students for field education and advanced study. It moves from person-in-environment foundations into development across the life course, then integrates attachment, trauma, culture, power, resilience, and applied assessment.',
  data = $hb1json${"slug": "human-behavior-in-the-social-environment-i", "title": "Human Behavior in the Social Environment I", "description": "This syllabus follows a lifespan-development base while incorporating biopsychosocial-spiritual formulation, neuroscience, structural context, trauma/ACEs, culture and power analysis, and applied case assessment. This sequence fits a Social Work core course that prepares students for field education and advanced study. It moves from person-in-environment foundations into development across the life course, then integrates attachment, trauma, culture, power, resilience, and applied assessment.", "topics": [{"id": "748af73f-71ab-4026-becc-5d9f756f5989", "type": "topic", "title": "HBSE I as a Person-in-Environment Foundation", "description": "Frame human behavior as the interaction of individuals, relationships, institutions, culture, biology, history, and environment across the life course.", "children": [{"id": "8b0cd10d-e965-4f75-aca4-5d3a12bb7443", "type": "subtopic", "title": "Purpose of HBSE in social work", "children": [{"id": "f1dd96e3-c9e8-4540-8593-bcab798eab8a", "type": "concept", "title": "Person-in-environment tradition"}, {"id": "12f1a7be-0dd4-4d9c-8ae2-b4e02f936d8d", "type": "concept", "title": "Generalist and advanced practice uses"}, {"id": "a5f69fe9-5c9c-4aa9-8090-5bc8bd997881", "type": "concept", "title": "Micro, mezzo, and macro connections"}, {"id": "8a41da2d-1ad4-40c2-a41b-45f92cd8f27d", "type": "concept", "title": "Theory-to-assessment-to-intervention logic"}], "description": "HBSE I gives social workers a theory-informed way to understand people without separating them from their environments."}, {"id": "6416a9f6-a1d2-4d0a-a332-a01e4f403827", "type": "subtopic", "title": "Life-course perspective", "children": [{"id": "3108912a-7759-40ed-aa73-7745bd3494a4", "type": "concept", "title": "Developmental trajectories"}, {"id": "0a968975-0419-4678-9a2f-6d09ad2b9198", "type": "concept", "title": "Transitions and turning points"}, {"id": "7b244c80-0ba5-4be0-8f4f-cefcb046d503", "type": "concept", "title": "Linked lives"}, {"id": "3ca35ab8-38f8-46ad-ab7a-5e1f2a88d04b", "type": "concept", "title": "Cohort and historical context"}], "description": "A life-course lens shows how timing, transitions, accumulated advantage, and accumulated adversity shape development."}, {"id": "f0be1b2b-7bf4-4c79-97f5-46b6fb079dad", "type": "subtopic", "title": "Evidence-informed humility", "children": [{"id": "8bdf25bb-4402-49ca-a2f8-6d8605ef52d6", "type": "concept", "title": "Research literacy"}, {"id": "b4dfaf08-ccc8-4918-835e-914385812e5d", "type": "concept", "title": "Practice wisdom"}, {"id": "eae8bcbe-d5d1-428e-9a62-8e7c470eb63f", "type": "concept", "title": "Client narratives"}, {"id": "938122b8-add5-4a9a-9b92-0cf071c0af13", "type": "concept", "title": "Avoiding deterministic explanations"}], "description": "Students learn to use research while respecting uncertainty, lived experience, culture, and client self-understanding."}]}, {"id": "4cdec673-aeff-4e85-b5d8-6d3d2c903a4c", "type": "topic", "title": "Biopsychosocial-Spiritual Assessment and Case Formulation", "description": "Build an integrated assessment lens that connects biological, psychological, social, spiritual, cultural, and structural dimensions.", "children": [{"id": "78cd0541-cfdb-4815-bb5e-01edbdc064c3", "type": "subtopic", "title": "Biological dimensions", "children": [{"id": "631a7f83-eb4b-4113-a42c-2eba232b078d", "type": "concept", "title": "Health status"}, {"id": "91b7ae55-9947-4324-afba-2c9c317f60be", "type": "concept", "title": "Disability"}, {"id": "7f42ee00-44dc-4312-976c-459592a5c1f6", "type": "concept", "title": "Sleep, nutrition, and pain"}, {"id": "ca6d3181-b1be-4fa9-b8f1-f39c864bfdf5", "type": "concept", "title": "Genetic and neurodevelopmental factors"}], "description": "Biological factors matter, but they are always interpreted alongside environment, meaning, and resources."}, {"id": "0c830293-838b-4986-b798-0e11d4065fd1", "type": "subtopic", "title": "Psychological and relational dimensions", "children": [{"id": "44433c96-751c-414c-b5a0-04bff2038bbd", "type": "concept", "title": "Emotion regulation"}, {"id": "d1081156-3a18-449d-8fe7-c89aa6572b63", "type": "concept", "title": "Cognition and meaning-making"}, {"id": "926329d8-491a-4633-ab8f-c1157c100eea", "type": "concept", "title": "Attachment and relational patterns"}, {"id": "d2557783-4e56-49ae-b4c6-714d3ccbd4e9", "type": "concept", "title": "Motivation and coping"}], "description": "Psychological functioning develops in relationships and contexts rather than in isolation."}, {"id": "9c0a5f0f-2008-420e-94f7-b5c834915d8d", "type": "subtopic", "title": "Social, spiritual, and structural dimensions", "children": [{"id": "4fa61181-9aca-4d7a-9726-5d06a93f6b23", "type": "concept", "title": "Family and community supports"}, {"id": "2bf08ccf-1e7b-4e9c-a902-6e942d16dc46", "type": "concept", "title": "Culture and spirituality"}, {"id": "729ac187-97e8-4be4-b09f-8f75f0325e73", "type": "concept", "title": "Housing, income, and safety"}, {"id": "a2d29d66-fd4a-4b38-8ad0-dbc3df0211e1", "type": "concept", "title": "Discrimination and institutional barriers"}], "description": "A strong formulation includes the client's social world, identity, values, and structural conditions."}]}, {"id": "58dc3186-d6f3-4325-b78b-bbf4359b7d8d", "type": "topic", "title": "Major Theories of Human Development and Behavior", "description": "Compare developmental, psychodynamic, behavioral, cognitive, systems, feminist, critical, and strengths-based theories for social work use.", "children": [{"id": "f70c3ab2-d0a6-460e-ae26-e436b1fa4962", "type": "subtopic", "title": "Developmental theories", "children": [{"id": "135dba64-e181-46a7-877a-95c09f378a51", "type": "concept", "title": "Erikson"}, {"id": "6b5bb570-aa62-423b-b3f6-71c893336e0e", "type": "concept", "title": "Piaget"}, {"id": "8f0b4ab2-9148-419b-812d-594e98b731dc", "type": "concept", "title": "Vygotsky"}, {"id": "e71bed9f-9a9c-418a-85f0-faf44c4b84aa", "type": "concept", "title": "Life-course theory"}], "description": "Developmental theories help students organize change across childhood, adolescence, adulthood, and aging."}, {"id": "f34196e7-87e1-4d50-9400-1fde88de6eb3", "type": "subtopic", "title": "Behavioral, cognitive, and learning theories", "children": [{"id": "9a634139-50c4-49c0-aa25-ce27e03ff220", "type": "concept", "title": "Classical and operant conditioning"}, {"id": "6a9b111d-f4ae-4d27-b57a-968cb0d18986", "type": "concept", "title": "Social learning"}, {"id": "88922bce-b73f-444b-a96e-e9384924fe68", "type": "concept", "title": "Cognitive development"}, {"id": "846382c2-9814-4a29-86bb-bdef6ea1447a", "type": "concept", "title": "Cognitive-behavioral concepts"}], "description": "Learning theories explain behavior, change, reinforcement, cognition, and skill development."}, {"id": "68157b3f-829f-4136-9c4f-bf4c671fca2f", "type": "subtopic", "title": "Critical, systems, and strengths theories", "children": [{"id": "4230c62c-4f4d-4378-b0e3-7f0bd7af1bf5", "type": "concept", "title": "Systems theory"}, {"id": "bfb4c733-f509-4d0b-a687-09ae77654057", "type": "concept", "title": "Strengths perspective"}, {"id": "73589158-dadb-43d5-aafc-f20f747f6427", "type": "concept", "title": "Feminist and critical race perspectives"}, {"id": "d846d8b8-4376-4e01-a83f-f11ce916cbd6", "type": "concept", "title": "Empowerment and anti-oppressive practice"}], "description": "This course requires theories that address power, environments, resilience, and social change."}]}, {"id": "39e73e7f-6a78-4d10-b101-297946152352", "type": "topic", "title": "Ecological Systems, Social Determinants, and Structural Context", "description": "Analyze how families, schools, communities, policy, economic conditions, racism, and oppression shape developmental pathways.", "children": [{"id": "34e06015-b84a-42e3-ac51-185133ba24f9", "type": "subtopic", "title": "Ecological systems theory", "children": [{"id": "3991cb45-3d7c-4dba-8462-6dcc20d94d1e", "type": "concept", "title": "Microsystem"}, {"id": "e66b0457-2393-488e-aae8-017b3eda2f62", "type": "concept", "title": "Mesosystem"}, {"id": "e7ac89ae-8cf7-4460-8bbb-dd9f3cb91eee", "type": "concept", "title": "Exosystem"}, {"id": "e9cb1ce9-644a-42ca-b2ca-275bf8f52934", "type": "concept", "title": "Macrosystem and chronosystem"}], "description": "Ecological thinking helps students locate behavior within nested environments."}, {"id": "66edcfd0-fb65-47df-8db7-3c12e56c0cda", "type": "subtopic", "title": "Social determinants of development", "children": [{"id": "4c77cb02-b688-4e84-9947-84c4cd39cf64", "type": "concept", "title": "Housing and neighborhood conditions"}, {"id": "ab788727-e898-4a38-90e8-88a3a2eb3751", "type": "concept", "title": "Education and employment"}, {"id": "f26e0dd4-c309-41c3-a883-03569113836e", "type": "concept", "title": "Health care access"}, {"id": "d1d80625-61e1-40b2-ae4a-d47ea09850d1", "type": "concept", "title": "Food security and transportation"}], "description": "Development is shaped by material and social conditions as much as individual choice."}, {"id": "7caea24e-085e-4f69-86c4-54220ca534f2", "type": "subtopic", "title": "Structural oppression and opportunity", "children": [{"id": "d5ea1511-a24c-4c64-8615-4837cc56bf08", "type": "concept", "title": "Racism and segregation"}, {"id": "57ef15b1-c432-4353-93ea-e6f5dd5ee514", "type": "concept", "title": "Class inequality"}, {"id": "b3bef552-ef0f-403f-bec3-ae8f4a421ed3", "type": "concept", "title": "Ableism and ageism"}, {"id": "24b107f2-83b0-49d7-9cd2-a311028959a0", "type": "concept", "title": "Policy and institutional power"}], "description": "Students learn how inequity is produced by systems and experienced in individual lives."}]}, {"id": "feb34e57-1091-4de1-ad7e-1e40e29128ab", "type": "topic", "title": "Neuroscience, Genetics, Temperament, and Human Behavior", "description": "Use core brain, body, and behavioral science without reducing human experience to biology alone.", "children": [{"id": "4f69289c-1222-4c66-9f9e-d0e5dbd4019c", "type": "subtopic", "title": "Brain development and plasticity", "children": [{"id": "d8141278-eb20-4e1c-9be4-6a981d012fe2", "type": "concept", "title": "Neural plasticity"}, {"id": "4ce71e53-9aac-47d8-a4dc-a9f7e5b957b6", "type": "concept", "title": "Executive function"}, {"id": "c4c4aa36-a16d-490e-bdf9-00dff33e3792", "type": "concept", "title": "Emotion and threat systems"}, {"id": "db2c3565-7dc5-4897-a1f1-50afdc5cdb37", "type": "concept", "title": "Sensitive periods"}], "description": "Basic neuroscience clarifies how experience can shape brain development and adaptation."}, {"id": "c44cf61c-9a27-4964-af93-44e75a980166", "type": "subtopic", "title": "Genes, environment, and temperament", "children": [{"id": "3a506b86-c260-41ff-a917-02cc8e3b3a4d", "type": "concept", "title": "Gene-environment interaction"}, {"id": "98c4273a-d7b3-43e2-a04b-1c3610c20187", "type": "concept", "title": "Epigenetics basics"}, {"id": "cec41a34-d64d-487d-98d3-266e7bcd1be1", "type": "concept", "title": "Temperament"}, {"id": "ca07ce51-51b0-43cb-8705-92dea478347b", "type": "concept", "title": "Differential susceptibility"}], "description": "Students learn to avoid nature-versus-nurture simplifications and understand reciprocal influence."}, {"id": "b811e2a5-a5f9-4f4e-ac37-e1cbbf4a815c", "type": "subtopic", "title": "Neuroscience in ethical practice", "children": [{"id": "8860c5c0-2622-41e3-84e4-3e41410b0a5e", "type": "concept", "title": "Brain-based explanations"}, {"id": "d3acc304-96f1-4a25-abde-c86ae1c28f9d", "type": "concept", "title": "Limits of neurobiological evidence"}, {"id": "39cd01af-8a77-4ed0-a21a-60cfdd5f1880", "type": "concept", "title": "Cultural interpretation of behavior"}, {"id": "a1ab5745-648b-4be4-9d74-8302de9fdc0e", "type": "concept", "title": "Client dignity and agency"}], "description": "Neuroscience can deepen empathy, but it must not become reductionist or stigmatizing."}]}, {"id": "190688a5-ce8a-4403-8a89-5165aca0c624", "type": "topic", "title": "Prenatal Development, Infancy, and Early Childhood", "description": "Understand the earliest developmental periods, caregiver relationships, attachment, stress, and protective environments.", "children": [{"id": "93905dcf-ce3b-4c8c-bc5e-c067aac76c3f", "type": "subtopic", "title": "Prenatal and perinatal development", "children": [{"id": "059b5961-be40-4399-92b2-c80f93055c17", "type": "concept", "title": "Prenatal care"}, {"id": "39e0d532-241d-424e-8e8c-ece554dcc6b9", "type": "concept", "title": "Substance exposure"}, {"id": "468ad059-fbe5-4660-95e1-0bf5bc8c98af", "type": "concept", "title": "Maternal stress and support"}, {"id": "4e01dc28-9812-416d-8672-9b0b251b94f5", "type": "concept", "title": "Birth outcomes and inequities"}], "description": "Early development begins before birth and is shaped by health, stress, care, and social conditions."}, {"id": "ca805a1e-7e6c-4e61-bfd9-f889ddbe608f", "type": "subtopic", "title": "Infancy and attachment beginnings", "children": [{"id": "318de7d8-92bb-40c0-8c27-292bcb4294e5", "type": "concept", "title": "Attachment signals"}, {"id": "9254e6dc-07d0-4744-aa6c-9eba5fdb155f", "type": "concept", "title": "Serve-and-return interaction"}, {"id": "8a3f23a7-36fc-475e-a693-1fe1bcba0517", "type": "concept", "title": "Caregiver responsiveness"}, {"id": "2b78b481-3b68-4830-b268-52ee780de0bf", "type": "concept", "title": "Early intervention"}], "description": "Infancy highlights dependence, co-regulation, sensory development, and the foundations of trust."}, {"id": "3b6004da-af18-4b6a-848a-98260786d482", "type": "subtopic", "title": "Early childhood development", "children": [{"id": "9a1ed4bc-438c-4b79-a6a7-edacef49f247", "type": "concept", "title": "Language development"}, {"id": "8966ffc0-c97a-42e1-9925-f6d562095ed2", "type": "concept", "title": "Play and symbolic thought"}, {"id": "1f7c0d25-18fe-49b6-be93-d5d8be99ef16", "type": "concept", "title": "Self-regulation"}, {"id": "01b0c4bd-a616-49e0-b6b2-10f592592a79", "type": "concept", "title": "Early adversity and protective routines"}], "description": "Early childhood is a period of rapid growth in language, play, emotion regulation, and social learning."}]}, {"id": "35ddd641-b596-4a5c-85cb-423515766b60", "type": "topic", "title": "Middle Childhood: Learning, Peer Worlds, and Identity Formation", "description": "Study how children develop competence, emotion regulation, morality, culture, school belonging, and self-understanding.", "children": [{"id": "0e3c2e1e-7964-478e-8b85-9fc28f870644", "type": "subtopic", "title": "Cognitive and school development", "children": [{"id": "74ce0301-1ac9-4f30-9a2e-fa08be495476", "type": "concept", "title": "Concrete operations"}, {"id": "822c1621-b943-4016-b3f5-96cc31ab2139", "type": "concept", "title": "Executive function"}, {"id": "0ec31f86-c67b-43ce-9a6e-facc72cd4758", "type": "concept", "title": "Academic self-concept"}, {"id": "8f3902ad-be9b-456c-bcdc-ddd0b5e32d17", "type": "concept", "title": "Learning differences and disability"}], "description": "Middle childhood expands children's capacities for learning, problem solving, and competence."}, {"id": "f7f1564b-21cf-4c3d-b1ce-6a634a81290e", "type": "subtopic", "title": "Peers, morality, and social belonging", "children": [{"id": "f47dd719-0d09-4f42-acf3-89610a261324", "type": "concept", "title": "Friendship and peer acceptance"}, {"id": "e0f72bcb-d118-4c39-9422-d2159d82df47", "type": "concept", "title": "Bullying and exclusion"}, {"id": "d1490d04-1865-4dd1-a096-b5f2450487ce", "type": "concept", "title": "Moral reasoning"}, {"id": "03d4e255-a403-4a1f-bcc8-2ceb22e01f0f", "type": "concept", "title": "Belonging and school connectedness"}], "description": "Children develop identity and moral reasoning through peer systems, family norms, school climate, and culture."}, {"id": "b58ebe06-bd76-4afd-88f9-cff85ae5add0", "type": "subtopic", "title": "Family, community, and risk context", "children": [{"id": "3737da8c-9516-45f2-86fd-5b2ab822ca33", "type": "concept", "title": "Family routines"}, {"id": "45e4cf15-a094-426b-93db-fd04f863a7c4", "type": "concept", "title": "Community violence exposure"}, {"id": "d8cbbef6-48b7-4a12-b611-ab25f032f237", "type": "concept", "title": "Child welfare and school systems"}, {"id": "3c388a9a-3e44-449e-9ac0-6c044cf261aa", "type": "concept", "title": "Protective adults and mentoring"}], "description": "Middle childhood outcomes are shaped by caregiver support, neighborhood safety, resources, and institutional response."}]}, {"id": "c069f58a-45c7-4ca5-98bc-5f2b08340036", "type": "topic", "title": "Adolescence: Brain Development, Identity, Risk, and Belonging", "description": "Interpret adolescent behavior through development, context, identity, peer systems, trauma, and opportunity structures.", "children": [{"id": "94b75dfe-c8a9-441d-8fd8-4d9b7828c49d", "type": "subtopic", "title": "Adolescent brain and body development", "children": [{"id": "761ab337-74ae-4105-ae94-728ff353cd62", "type": "concept", "title": "Puberty"}, {"id": "38bfaa9a-b6f6-4f05-bfcf-e00c8540c198", "type": "concept", "title": "Reward sensitivity"}, {"id": "61b48f7a-6ab5-4465-94c1-bb8dcca2b9f4", "type": "concept", "title": "Executive function maturation"}, {"id": "97705a9b-ac42-44b2-8b7b-eb21f4e9df5c", "type": "concept", "title": "Sleep and health behavior"}], "description": "Adolescence is a major developmental reorganization, not simply a period of risk."}, {"id": "bfbbf105-d79d-4635-9f4d-626dc9bde641", "type": "subtopic", "title": "Identity and belonging", "children": [{"id": "525c3756-60c4-42d0-a6ce-dc8586f6330c", "type": "concept", "title": "Race and ethnic identity"}, {"id": "b6ece65d-b1fc-4c92-abd6-fee7576acbc2", "type": "concept", "title": "Gender and sexuality"}, {"id": "b44942e7-7a95-425c-a02a-3b0506dc8639", "type": "concept", "title": "Faith and values"}, {"id": "781a0f37-3300-4ab4-96da-8f7e526e0e0b", "type": "concept", "title": "Peer groups and online identity"}], "description": "Identity development is shaped by culture, relationships, opportunity, and recognition."}, {"id": "b581e0e5-c8b8-42d9-b171-129063b4c24d", "type": "subtopic", "title": "Risk, resilience, and opportunity", "children": [{"id": "7d6e2c34-02ef-460c-9673-1a68517a8c47", "type": "concept", "title": "Substance use and risk behavior"}, {"id": "c45339bc-9b4d-4d91-9925-ee8f294e12ee", "type": "concept", "title": "Mental health and suicide risk"}, {"id": "fd0cfb58-3024-4464-a715-93cfae447017", "type": "concept", "title": "Juvenile justice contact"}, {"id": "f47a3cf9-731a-4783-a292-41a930c834f1", "type": "concept", "title": "Youth voice and leadership"}], "description": "Students learn to distinguish normative exploration from danger and to identify protective contexts."}]}, {"id": "96a057e6-ecf9-46fd-bd0f-3f8a2df05c04", "type": "topic", "title": "Young Adulthood: Intimacy, Education, Work, and Emerging Roles", "description": "Examine early adult transitions, relationships, work, identity, mental health, and social expectations.", "children": [{"id": "6d410365-d4bb-42b6-b5b2-028142339296", "type": "subtopic", "title": "Emerging adulthood and transitions", "children": [{"id": "0d31cc0e-c262-455e-96b8-be775ea7e2c7", "type": "concept", "title": "Emerging adulthood debates"}, {"id": "ec3bddf2-4d6b-4c5f-a789-7687ade60410", "type": "concept", "title": "Higher education and vocational pathways"}, {"id": "3825f065-4042-40ba-ade4-5724c859c004", "type": "concept", "title": "Housing transitions"}, {"id": "2535cdeb-dd0a-4883-997f-da6b7c5fa7ea", "type": "concept", "title": "Financial stress"}], "description": "Young adulthood often involves uneven transitions into work, education, independence, and adult identity."}, {"id": "a0133901-0e0c-48b7-af5d-7506d222e96e", "type": "subtopic", "title": "Relationships and intimacy", "children": [{"id": "50b6d4e9-5be5-484f-9ed4-740f9688fd6c", "type": "concept", "title": "Friendship networks"}, {"id": "5fd7470d-0b08-4866-bdea-4f652c35c564", "type": "concept", "title": "Romantic relationships"}, {"id": "176fc6fc-8ce0-4a75-951c-c6f3a1e08616", "type": "concept", "title": "Consent and intimate partner violence"}, {"id": "6b266515-1c62-4364-a635-8f1ce9e8d3f2", "type": "concept", "title": "Family-of-origin renegotiation"}], "description": "Relationship development becomes a central context for identity, support, and vulnerability."}, {"id": "c8173b13-ddc8-4a75-ba4f-d7fc6cca9afb", "type": "subtopic", "title": "Mental health and social expectations", "children": [{"id": "250c6c53-2a03-438b-a6c3-35d31d47fd6b", "type": "concept", "title": "Depression and anxiety"}, {"id": "d08be397-74a6-44c5-87f8-45b7fcf85517", "type": "concept", "title": "Substance use"}, {"id": "c15d8081-76ac-4058-a057-e1443aa76290", "type": "concept", "title": "Work and career identity"}, {"id": "e01daf65-141d-4493-bef0-ec6431d5587a", "type": "concept", "title": "Cultural expectations of adulthood"}], "description": "Young adults face developmental pressure that is shaped by inequality and cultural scripts."}]}, {"id": "e2d3595e-1be7-4b79-bb42-5421510114af", "type": "topic", "title": "Middle Adulthood: Care, Work, Family, Health, and Generativity", "description": "Understand midlife development through caregiving, work, family systems, health, culture, and social responsibility.", "children": [{"id": "b7e4ca23-5c09-439d-b693-1c4e89e9eb86", "type": "subtopic", "title": "Work, family, and caregiving roles", "children": [{"id": "1008a914-fe07-4571-bbfd-128d63bf5b73", "type": "concept", "title": "Parenting and co-parenting"}, {"id": "2569bee5-487b-4069-b744-f243d401af7b", "type": "concept", "title": "Care for aging relatives"}, {"id": "6f8b07d6-a9af-4483-b0b2-05aae0d52d34", "type": "concept", "title": "Workplace stress"}, {"id": "1866d025-e779-481b-b5dd-6b4499fc298e", "type": "concept", "title": "Work-family conflict"}], "description": "Middle adulthood often involves layered responsibilities across generations and institutions."}, {"i