ty"}, {"id": "32fa7e92-6f1d-4d47-9577-0fb59d82a6b9", "type": "concept", "title": "Client-defined goals and dignity"}], "description": "Students learn to connect individual development with social justice and ethical practice."}]}, {"id": "dc70d013-b607-4a52-b59b-f93716218b67", "type": "topic", "title": "Person-in-Environment Assessment Lab and Integrative Case Application", "description": "Apply the course through developmentally grounded, culturally responsive, ethically sound case formulation and intervention reasoning.", "children": [{"id": "61b4b269-95ab-4915-be7f-a5845bdcc7a8", "type": "subtopic", "title": "Developmentally informed case assessment", "children": [{"id": "ad90f1b1-4f94-4e5b-951d-4c60734cfe8d", "type": "concept", "title": "Developmental timeline"}, {"id": "788089a3-27e7-44bd-9c69-c14f1212c7b5", "type": "concept", "title": "Risk and protective factors"}, {"id": "9eb8109f-f761-4546-a5a8-f1965a7e3e73", "type": "concept", "title": "Strengths and needs"}, {"id": "607edd54-4e3e-49f9-9019-d99687093c13", "type": "concept", "title": "Culture and context"}], "description": "Students practice translating theory into assessment questions and case formulation."}, {"id": "2a648bd4-3f19-4a2b-8694-c65b8823afcc", "type": "subtopic", "title": "Formulation and intervention reasoning", "children": [{"id": "50e9932c-6361-4010-a350-966492b1b99f", "type": "concept", "title": "Hypothesis building"}, {"id": "d136577a-500f-4f53-aafd-b4d80413f08b", "type": "concept", "title": "Competing explanations"}, {"id": "d253bbf7-0f85-4fe2-a0b9-8df215833fdb", "type": "concept", "title": "Intervention targets"}, {"id": "f730d892-723b-4a33-b8de-820cdd28a7c4", "type": "concept", "title": "Referral and collaboration"}], "description": "Formulation links what is happening, why it may be happening, and what could help."}, {"id": "ffa0df18-0c8c-4323-a8c4-adc3d9ac0874", "type": "subtopic", "title": "Ethics, reflection, and professional use of self", "children": [{"id": "a4b31e7b-ccb5-480c-aad